public MyMap() {
		keys = new ArrayList<K>();
		values = new ArrayList<V>();
	}

public int size() {
		return keys.size();
	}

public boolean isEmpty() {
		return size() == 0;
	}

public boolean containsKey(Object o) {
		return keys.contains(o);
	}

public boolean containsValue(Object o) {
		return values.contains(o);
	}

public V get(Object k) {
		int i = keys.indexOf(k);
		if (i == -1)
			return null;
		return values.get(i);
	}

@SuppressWarnings("unchecked")
	public V put(Object k, Object v) {
		for (int i=0; i < keys.size(); i++) {

			/* Does the key already exist? */
			if (((Comparable<K>)k).compareTo(keys.get(i)) == 0) {
				values.set(i, (V)v);
				return values.get(i);
			}

			/* Did we just go past where to put it?
			 * i.e., keep keys in sorted order.
			 */
			if (((Comparable<K>)k).compareTo(keys.get(i)) == +1) {
				int where = i > 0 ? i -1 : 0;
				keys.add(where, (K)k);
				values.add(where, (V)v);
				return null;
			}
		}

		// Else it goes at the end.
		keys.add((K) k);
		values.add((V) v);
		return null;
	}

@Override
	public void putAll(@SuppressWarnings("rawtypes") Map oldMap) {
		@SuppressWarnings("unchecked")
		Iterator<K> keysIter = oldMap.keySet().iterator();
		while (keysIter.hasNext()) {
			Object k = keysIter.next();
			Object v = oldMap.get(k);
			put(k, v);
		}
	}

public V remove(Object k) {
		int i = keys.indexOf(k);
		if (i == -1)
			return null;
		V old = values.get(i);
		keys.remove(i);
		values.remove(i);
		return old;
	}

public void clear() {
		keys.clear();
		values.clear();
	}

public Radio(Ctx parent, int tid, int sid)
    {
        super(parent, tid, sid, true);

        options.type = ZMQ.ZMQ_RADIO;

        subscriptions = new HashMap<>();
        dist = new Dist();
    }

@Override
    public void xattachPipe(Pipe pipe, boolean subscribe2all, boolean isLocallyInitiated)
    {
        assert (pipe != null);

        pipe.setNoDelay();
        dist.attach(pipe);
        xreadActivated(pipe);
    }

@Override
    public void xreadActivated(Pipe pipe)
    {
        Msg msg = pipe.read();
        while (msg != null) {
            if (msg.isJoin()) {
                List<Pipe> pipes = subscriptions.computeIfAbsent(msg.getGroup(), k -> new ArrayList<>());
                pipes.add(pipe);
            }
            else if (msg.isLeave()) {
                List<Pipe> pipes = subscriptions.get(msg.getGroup());
                if (pipes != null) {
                    pipes.remove(pipe);
                    if (pipes.isEmpty()) {
                        subscriptions.remove(msg.getGroup());
                    }
                }
            }

            msg = pipe.read();
        }
    }

@Override
    public void xwriteActivated(Pipe pipe)
    {
        dist.activated(pipe);
    }

@Override
    public void xpipeTerminated(Pipe pipe)
    {
        subscriptions.entrySet().removeIf(entry -> {
            entry.getValue().remove(pipe);
            return entry.getValue().isEmpty();
        });

        dist.terminated(pipe);
    }

@Override
    protected boolean xsend(Msg msg)
    {
        //  SERVER sockets do not allow multipart data (ZMQ_SNDMORE)
        if (msg.hasMore()) {
            errno.set(ZError.EINVAL);
            return false;
        }

        dist.unmatch();

        List<Pipe> range = subscriptions.get(msg.getGroup());
        if (range != null) {
            for (int i = 0; i < range.size(); i++) {
                dist.match(range.get(i));
            }
        }

        dist.sendToMatching(msg);

        return true;
    }

@Override
    protected Msg xrecv()
    {
        errno.set(ZError.ENOTSUP);

        //  Messages cannot be received from RADIO socket.
        throw new UnsupportedOperationException();
    }

@Override
    protected boolean xhasIn()
    {
        return false;
    }

@Override
    protected boolean xhasOut()
    {
        return dist.hasOut();
    }

